// Scalar baseline library. Its 64-bit keys, interval edge handling and
// fixed-depth traversal are legacy limitations, not the target contract.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <stack>
#include <stdexcept>
#include <string>
#include <vector>
const int B=8;
const int PLANB_FIXED_DEPTH_START=7, PLANB_FIXED_DEPTH_END=1;
const int nodes_per_level[]={8,72,648,5832,52488,472392,4251528};
const int level_start_id[]={0,8,80,728,6560,59048,531440,4782968};
struct entry {
    uint64_t prefix;
    int length;
    int next_hop;
};

struct interval_edge {
    uint64_t address;
    int next_hop;

    bool operator<(const interval_edge& other) const {
        return address < other.address;
    }
};

struct BaselineLookup {
    std::vector<interval_edge> edges;

    void build(const std::vector<entry>& fib) {
        fprintf(stderr, "  Building baseline interval structure (%zu entries)... ", fib.size());
        fflush(stderr);

        // Convert prefixes to interval edges using the same algorithm as B+ tree
        std::vector<std::pair<std::pair<uint64_t, int>, int>> interval_pairs;
        for (const auto& f : fib) {
            uint64_t start = f.prefix;
            uint64_t end;
            if (f.length == 0)
                end = -1UL;
            else
                end = start + (1UL << (64 - f.length));

            interval_pairs.emplace_back(std::make_pair(start, f.length), f.next_hop);
            interval_pairs.emplace_back(std::make_pair(end, f.length), -1);  // -1 marks end edge
        }

        // Sort by address, then by length (shorter prefixes first = less specific)
        std::sort(interval_pairs.begin(), interval_pairs.end(),
            [](const auto& a, const auto& b) {
                if (a.first.first != b.first.first)
                    return a.first.first < b.first.first;
                return a.first.second < b.first.second;  // shorter length first
            });

        // Resolve overlaps using stack (longest prefix match)
        std::stack<int> nh;
        for (auto& e : interval_pairs) {
            if (e.second >= 0) {
                // Start edge: push the next_hop
                nh.push(e.second);
            } else {
                // End edge: pop and replace with new top if available
                assert(!nh.empty());
                nh.pop();
                if (!nh.empty())
                    e.second = nh.top();  // Store the next_hop that becomes active
            }
        }

        // Create edges for lookup
        // Store (address, next_hop) pairs where next_hop is active AFTER this address
        edges.reserve(interval_pairs.size());
        for (const auto& e : interval_pairs) {
            // Store all edges, including -1 for "no active prefix"
            edges.push_back({e.first.first, e.second});
        }

        // Sort by address for binary search
        // CRITICAL: Use stable sort to preserve order of edges with same address.
        // After stack resolution, start edges (next_hop >= 0) are created first,
        // then end edges (next_hop < 0). We need to maintain this order.
        std::stable_sort(edges.begin(), edges.end(),
            [](const interval_edge& a, const interval_edge& b) {
                if (a.address != b.address)
                    return a.address < b.address;
                // At same address: start edges (nh >= 0) before end edges (nh < 0)
                // This preserves the order: all start edges, then all end edges
                return (a.next_hop >= 0 && b.next_hop < 0);
            });

        fprintf(stderr, "done (%zu edges)\n", edges.size());
    }

    int lookup(uint64_t addr) const {
        // Use std::lower_bound to find the first edge with address > addr
        // Return the previous edge's next_hop (or 0 if no valid edge)
        if (edges.empty()) {
            return 0;  // Default next-hop
        }
        uint64_t target = (addr == UINT64_MAX) ? addr : addr + 1;
        auto it = std::lower_bound(
            edges.begin(), edges.end(), target,
            [](const interval_edge& e, uint64_t value) {
                return e.address < value;
            });

        if (it == edges.begin()) {
            return 0;  // Default next-hop
        }
        int nh = (it - 1)->next_hop;
        return (nh < 0) ? 0 : nh;  // -1 means no active prefix
    }

    size_t memory_usage() const {
        size_t total = edges.size() * sizeof(interval_edge);
        return total > 0 ? total : sizeof(edges);  // At least account for vector overhead
    }
};

struct BPTree {
    std::vector<int> next_hop;
    uint64_t *keys;
    uint32_t N;
    int DEPTH;

    BPTree() : keys(nullptr), N(0), DEPTH(-1) {}

    ~BPTree() {
        if (keys) {
            free(keys);
        }
    }

    // Common build process for all B+ tree variants
    void build(const std::vector<entry>& fib) {
        fprintf(stderr, "  Building B+ tree (%zu entries, depth)... ", fib.size());
        fflush(stderr);

        // Determine tree depth based on FIB size
        for (int i = 0; i < 7; i++) {
            if (nodes_per_level[i] >= (int)fib.size()) {
                DEPTH = i + 1;
                break;
            }
        }
        fprintf(stderr, "DEPTH = %d\n", DEPTH);

        // Create interval edges and resolve (same as baseline)
        std::vector<std::pair<std::pair<uint64_t, int>, int>> interval_pairs;
        for (const auto& f : fib) {
            uint64_t start = f.prefix;
            uint64_t end;
            if (f.length == 0)
                end = -1UL;
            else
                end = start + (1UL << (64 - f.length));

            interval_pairs.emplace_back(std::make_pair(start, f.length), f.next_hop);
            interval_pairs.emplace_back(std::make_pair(end, f.length), -1);
        }

        std::sort(interval_pairs.begin(), interval_pairs.end(),
            [](const auto& a, const auto& b) {
                if (a.first.first != b.first.first)
                    return a.first.first < b.first.first;
                return a.first.second < b.first.second;
            });

        // Resolve overlaps using stack
        std::stack<int> nh;
        for (auto& e : interval_pairs) {
            if (e.second >= 0) {
                nh.push(e.second);
            } else {
                assert(!nh.empty());
                nh.pop();
                if (!nh.empty())
                    e.second = nh.top();
            }
        }
        assert(nh.empty());

        // Create final lookup edges
        struct interval_edge {
            uint64_t address;
            int next_hop;
            bool operator<(const interval_edge& other) const {
                return address < other.address;
            }
        };
        std::vector<interval_edge> lookup_edges;
        lookup_edges.reserve(interval_pairs.size());
        for (const auto& e : interval_pairs) {
            lookup_edges.push_back({e.first.first, e.second});
        }

        // Stable sort
        std::stable_sort(lookup_edges.begin(), lookup_edges.end(),
            [](const interval_edge& a, const interval_edge& b) {
                if (a.address != b.address)
                    return a.address < b.address;
                return (a.next_hop >= 0 && b.next_hop < 0);
            });

        // Allocate tree array
        N = level_start_id[DEPTH];
        if (posix_memalign((void**)&keys, 64, N * sizeof(uint64_t)) != 0) {
            fprintf(stderr, "Error: Failed to allocate aligned memory for keys\n");
            exit(1);
        }
        uint64_t *keys_ptr = keys;

        auto leaf_start = level_start_id[DEPTH - 1];
        auto leaf_size = nodes_per_level[DEPTH - 1];

        // Resize next_hop to match edges size
        next_hop.resize(lookup_edges.size());

        // Populate leaf level with lookup edges
        size_t max_entries = std::min(lookup_edges.size(), (size_t)leaf_size);
        for (size_t j = 0; j < max_entries; ++j) {
            auto i = leaf_start + j;
            if (i < N) {
                keys_ptr[i] = lookup_edges[j].address;
                next_hop[j] = lookup_edges[j].next_hop;
            }
        }

        // Fill remaining leaf keys with max value
        for (auto i = leaf_start + max_entries; i < N; ++i) {
            keys_ptr[i] = -1UL;
        }

        // Build internal levels bottom-up
        auto G = B;
        for (auto level = DEPTH - 1; level > 0; --level) {
            auto pos = level_start_id[level - 1];
            for (auto i = 0; i < leaf_size; i += G * (B + 1)) {
                for (int j = 1; j <= B; j++) {
                    auto src_idx = leaf_start + i + G * j;
                    if (src_idx < N && pos < N) {  // Bounds check
                        keys_ptr[pos++] = keys_ptr[src_idx];
                    }
                }
            }
            G *= (B + 1);
        }

        fprintf(stderr, "done (depth=%d, N=%u)\n", DEPTH, N);
    }

    // Helper: calculate child index
    uint32_t child(uint32_t c, uint32_t i) const {
        return (B + 1) * i + (c + 1) * B;
    }

    int lookup_variant1(uint64_t x) const;
};


using Key=unsigned __int128;
inline std::string hexkey(Key x) {
    static const char*d="0123456789abcdef";std::string s(32,'0');
    for(int i=31;i>=0;--i){s[i]=d[unsigned(x&15)];x>>=4;}return s;
}
inline Key key(const std::string&s) {
    if(s.size()!=32)throw std::runtime_error("key width");
    Key value=0;for(char c:s){int d=c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;
        if(d<0)throw std::runtime_error("key digit");value=(value<<4)|d;}return value;
}

inline entry make_entry(const std::string&s,int length,int hop) {
    if(length>64)throw std::runtime_error("legacy route library lacks full-width prefixes");
    return {uint64_t(key(s)>>64),length,hop};
}
