#pragma once
// Scalar cache-budgeted FIDX v2 image library (full 128-bit unsigned keys).
// Replaces the legacy 64-bit/fixed-depth baseline with the protocol-3 contract:
// canonical forwarding runs, packed ordered-tree images and the joint
// tree/mode/residency optimizer.
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

using U128 = unsigned __int128;
const long long INFLL = (long long)4e18;

inline U128 parse_key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    U128 v = 0;
    for (char c : s) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else throw std::runtime_error("key digit");
        v = (v << 4) | (U128)(unsigned)d;
    }
    return v;
}

inline std::string hexkey(U128 x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[(unsigned)(x & 15)]; x >>= 4; }
    return s;
}

// A bound equal to 2^128 is spelled "1" followed by 32 zeros.
inline std::string hexbound(U128 x, bool upper) {
    return upper ? std::string("1") + std::string(32, '0') : hexkey(x);
}

inline void wr16(std::vector<uint8_t>& im, size_t o, unsigned v) {
    im[o] = (uint8_t)v; im[o + 1] = (uint8_t)(v >> 8);
}
inline void wr32(std::vector<uint8_t>& im, size_t o, uint32_t v) {
    for (int t = 0; t < 4; ++t) { im[o + t] = (uint8_t)(v & 255); v >>= 8; }
}
inline void wr64(std::vector<uint8_t>& im, size_t o, uint64_t v) {
    for (int t = 0; t < 8; ++t) { im[o + t] = (uint8_t)(v & 255); v >>= 8; }
}
inline void wr128(std::vector<uint8_t>& im, size_t o, U128 v) {
    for (int t = 0; t < 16; ++t) { im[o + t] = (uint8_t)(v & 255); v >>= 8; }
}
inline unsigned rd16(const std::vector<uint8_t>& im, size_t o) {
    return (unsigned)im[o] | ((unsigned)im[o + 1] << 8);
}
inline uint32_t rd32(const std::vector<uint8_t>& im, size_t o) {
    uint32_t v = 0;
    for (int t = 3; t >= 0; --t) v = (v << 8) | im[o + t];
    return v;
}
inline uint64_t rd64(const std::vector<uint8_t>& im, size_t o) {
    uint64_t v = 0;
    for (int t = 7; t >= 0; --t) v = (v << 8) | im[o + t];
    return v;
}
inline U128 rd128(const std::vector<uint8_t>& im, size_t o) {
    U128 v = 0;
    for (int t = 15; t >= 0; --t) v = (v << 8) | im[o + t];
    return v;
}

// ---------------------------------------------------------------- runs ------

struct Route { U128 start; int len; int hop; };
struct Run { U128 start; int hop; };  // hop -1 means null

// Canonical maximal forwarding runs over [0,2^128): sweep all prefix
// boundaries, keep the active longest-prefix hop, coalesce equal neighbours.
inline std::vector<Run> compile_runs(const std::vector<Route>& routes) {
    struct Ev { U128 pos; int len; int delta; int hop; };
    std::vector<Ev> ev;
    ev.reserve(routes.size() * 2);
    for (const Route& r : routes) {
        if (r.len < 0 || r.len > 128) throw std::runtime_error("prefix length");
        ev.push_back({r.start, r.len, 1, r.hop});
        if (r.len > 0) {
            U128 size = U128(1) << (128 - r.len);
            U128 end = r.start + size;
            // end == 0 exactly means the prefix runs to 2^128 (wraps).
            if (end != 0) ev.push_back({end, r.len, -1, r.hop});
        }
    }
    std::sort(ev.begin(), ev.end(), [](const Ev& a, const Ev& b) {
        return a.pos < b.pos;
    });
    int cnt[129], cur[129];
    for (int i = 0; i < 129; ++i) { cnt[i] = 0; cur[i] = -1; }
    std::vector<Run> runs;
    U128 prev = 0;
    size_t k = 0;
    auto top = [&]() {
        for (int L = 128; L >= 0; --L) if (cnt[L] > 0) return cur[L];
        return -1;
    };
    while (k < ev.size()) {
        U128 p = ev[k].pos;
        if (prev < p) {
            int hop = top();
            if (runs.empty() || runs.back().hop != hop) runs.push_back({prev, hop});
        }
        while (k < ev.size() && ev[k].pos == p) {
            if (ev[k].delta > 0) { cnt[ev[k].len]++; cur[ev[k].len] = ev[k].hop; }
            else cnt[ev[k].len]--;
            ++k;
        }
        prev = p;
    }
    {
        int hop = top();
        if (runs.empty() || runs.back().hop != hop) runs.push_back({prev, hop});
    }
    return runs;
}

// Forwarding-change row between two consecutive versions.
struct ChangeRow {
    U128 start, end;
    bool end_upper;  // end == 2^128
    int old_hop, new_hop;
};

inline std::vector<ChangeRow> diff_runs(const std::vector<Run>& a, const std::vector<Run>& b) {
    std::vector<ChangeRow> out;
    size_t ia = 0, ib = 0;
    U128 pos = 0;
    for (;;) {
        bool naU = !(ia + 1 < a.size()), nbU = !(ib + 1 < b.size());
        U128 na = naU ? U128(0) : a[ia + 1].start;
        U128 nb = nbU ? U128(0) : b[ib + 1].start;
        bool endU;
        U128 endv = 0;
        if (naU && nbU) endU = true;
        else if (naU) { endU = false; endv = nb; }
        else if (nbU) { endU = false; endv = na; }
        else { endU = false; endv = std::min(na, nb); }
        int oh = a[ia].hop, nh = b[ib].hop;
        if (oh != nh) {
            if (!out.empty() && out.back().old_hop == oh && out.back().new_hop == nh &&
                !out.back().end_upper && out.back().end == pos) {
                out.back().end = endv;
                out.back().end_upper = endU;
            } else {
                out.push_back({pos, endv, endU, oh, nh});
            }
        }
        if (endU) break;
        if (!naU && endv == na) ++ia;
        if (!nbU && endv == nb) ++ib;
        pos = endv;
    }
    return out;
}

// --------------------------------------------------------------- images -----

struct LayoutNode {
    int kind;   // 0 internal, 1 leaf
    int mode;   // 0,1,2
    int cached; // 0,1
    int lo, span;
    std::vector<int> kids;  // BFS-order indices of children, left to right
};

inline int node_alloc(int kind, int mode, int span, int b) {
    static const int width[3] = {16, 8, 4};
    int K = (kind == 0) ? b - 1 : span;
    int used = 32 + 4 * b + K * width[mode];
    return ((used + 63) / 64) * 64;
}

// Unique exact FIDX version-2 byte image for the supplied layout.
inline std::vector<uint8_t> build_image(const std::vector<U128>& starts,
                                        const std::vector<int>& hops,
                                        const std::vector<LayoutNode>& nodes) {
    static const int width[3] = {16, 8, 4};
    int R = (int)starts.size();
    size_t n = nodes.size();
    std::vector<uint32_t> alloc(n), off(n);
    uint32_t cursor = 64;
    for (size_t t = 0; t < n; ++t) {
        int b = (int)nodes[t].kids.size();
        alloc[t] = (uint32_t)node_alloc(nodes[t].kind, nodes[t].mode, nodes[t].span, b);
        off[t] = cursor;
        cursor += alloc[t];
    }
    uint32_t hopoff = cursor;
    uint32_t hopbytes = (uint32_t)(((4 * R + 63) / 64) * 64);
    uint32_t total = hopoff + hopbytes;
    std::vector<uint8_t> img(total, 0);
    img[0] = 'F'; img[1] = 'I'; img[2] = 'D'; img[3] = 'X';
    img[4] = 2;
    wr32(img, 8, (uint32_t)R);
    wr32(img, 12, (uint32_t)n);
    wr32(img, 16, hopoff);
    wr32(img, 20, total);
    for (size_t t = 0; t < n; ++t) {
        const LayoutNode& nd = nodes[t];
        uint32_t o = off[t];
        int b = (int)nd.kids.size();
        int K = (nd.kind == 0) ? b - 1 : nd.span;
        img[o] = (uint8_t)nd.kind;
        img[o + 1] = (uint8_t)nd.mode;
        img[o + 2] = (uint8_t)nd.cached;
        wr16(img, o + 4, (unsigned)nd.lo);
        wr16(img, o + 6, (unsigned)nd.span);
        wr16(img, o + 8, (unsigned)((nd.kind == 0) ? b : nd.span));
        wr32(img, o + 12, alloc[t]);
        U128 base = starts[nd.lo];
        wr128(img, o + 16, base);
        uint32_t at = o + 32;
        if (nd.kind == 0) {
            for (int c : nd.kids) { wr32(img, at, off[c]); at += 4; }
        }
        for (int q = 0; q < K; ++q) {
            U128 key = (nd.kind == 0) ? starts[nodes[nd.kids[q + 1]].lo]
                                      : starts[nd.lo + q];
            if (nd.mode == 0) wr128(img, at, key);
            else if (nd.mode == 1) wr64(img, at, (uint64_t)(key - base));
            else wr32(img, at, (uint32_t)(key - base));
            at += width[nd.mode];
        }
    }
    for (int r = 0; r < R; ++r)
        wr32(img, hopoff + 4 * (size_t)r, hops[r] < 0 ? 0xffffffffu : (uint32_t)hops[r]);
    return img;
}

struct Answer {
    int hop;   // -1 = null
    long long run;
    std::vector<uint32_t> path;
};

// Actual packed-image lookup kernel: root-to-leaf byte-offset path, run index.
inline Answer trace_image(const std::vector<uint8_t>& img, U128 addr) {
    static const int width[3] = {16, 8, 4};
    uint32_t hopoff = rd32(img, 16);
    Answer res;
    uint32_t o = 64;
    for (;;) {
        res.path.push_back(o);
        int kind = img[o], mode = img[o + 1];
        int lo = (int)rd16(img, o + 4), span = (int)rd16(img, o + 6);
        int count = (int)rd16(img, o + 8);
        U128 base = rd128(img, o + 16);
        if (kind == 1) {
            int idx = -1;
            uint32_t at = o + 32;
            for (int q = 0; q < span; ++q) {
                U128 key = (mode == 0) ? rd128(img, at)
                    : base + (U128)((mode == 1) ? rd64(img, at) : rd32(img, at));
                if (key <= addr) idx = q;
                at += width[mode];
            }
            res.run = lo + idx;
            uint32_t h = rd32(img, hopoff + 4 * (size_t)res.run);
            res.hop = (h == 0xffffffffu) ? -1 : (int)h;
            return res;
        }
        int b = count, c = 0;
        uint32_t at = o + 32 + 4 * (uint32_t)b;
        for (int q = 0; q + 1 < b; ++q) {
            U128 key = (mode == 0) ? rd128(img, at)
                : base + (U128)((mode == 1) ? rd64(img, at) : rd32(img, at));
            if (key <= addr) c = q + 1;
            at += width[mode];
        }
        o = rd32(img, o + 32 + 4 * (uint32_t)c);
    }
}

// ------------------------------------------------------------- optimizer ----

struct BurstData {
    long long rep;
    std::vector<int> cnt;  // per-run address counts
};

struct OptPair { long long w; int p; };

inline bool pair_less(long long wa, int pa, long long wb, int pb) {
    return wa < wb || (wa == wb && pa < pb);
}

// One version's joint tree/mode/residency plan.  F(i,j,p) = best (work,pages)
// for a subtree covering runs [i,j) using exactly p cached pages; G(i,j,k,p)
// is the same for a forest of exactly k ordered subtrees.
struct VersionPlan {
    int R = 0, C = 0, hit = 0, miss = 0;
    int dec[3] = {0, 0, 0};
    std::vector<long long> Q, T;   // flat (R+1)*(R+1), ranges [i,j)
    std::vector<long long> Fw, Gw;
    std::vector<int> Fp, Gp;
    std::vector<int> Fc, Gc;
    std::vector<OptPair> best;     // size C+1
    std::vector<U128> starts;

    inline int IJ(int i, int j) const { return i * (R + 1) + j; }
    inline int fidx(int i, int j, int p) const { return (IJ(i, j) * (C + 1) + p); }
    inline int gidx(int k, int i, int j, int p) const {
        return ((k * (R + 1) * (R + 1) + IJ(i, j)) * (C + 1) + p);
    }
    inline bool legal(int i, int j, int mode) const {
        if (mode == 0) return true;
        U128 spread = starts[j - 1] - starts[i];
        if (mode == 1) return (spread >> 64) == 0;
        return (spread >> 32) == 0;
    }

    void run(const std::vector<U128>& st, const std::vector<BurstData>& bursts,
             int budget, int h, int m, const int* dc) {
        starts = st;
        R = (int)st.size();
        C = budget; hit = h; miss = m;
        dec[0] = dc[0]; dec[1] = dc[1]; dec[2] = dc[2];
        int sm = (R + 1) * (R + 1);
        Q.assign((size_t)sm, 0);
        T.assign((size_t)sm, 0);
        for (const BurstData& b : bursts) {
            std::vector<long long> pref(R + 1, 0);
            for (int r = 0; r < R; ++r) pref[r + 1] = pref[r] + b.cnt[r];
            for (int i = 0; i < R; ++i)
                for (int j = i + 1; j <= R; ++j) {
                    long long c = pref[j] - pref[i];
                    Q[(size_t)IJ(i, j)] += b.rep * c;
                    if (c > 0) T[(size_t)IJ(i, j)] += b.rep;
                }
        }
        size_t fs = (size_t)sm * (C + 1);
        size_t gs = (size_t)10 * sm * (C + 1);
        Fw.assign(fs, INFLL); Fp.assign(fs, 0); Fc.assign(fs, -1);
        Gw.assign(gs, INFLL); Gp.assign(gs, 0); Gc.assign(gs, -1);
        static const int width[3] = {16, 8, 4};
        static const int lanes[3] = {4, 8, 16};
        auto updF = [&](int i, int j, int p, long long w, int pg, int ch) {
            size_t t = (size_t)fidx(i, j, p);
            if (w < Fw[t] || (w == Fw[t] && pg < Fp[t])) {
                Fw[t] = w; Fp[t] = pg; Fc[t] = ch;
            }
        };
        for (int L = 1; L <= R; ++L) {
            for (int i = 0; i + L <= R; ++i) {
                int j = i + L;
                long long qq = Q[(size_t)IJ(i, j)], tt = T[(size_t)IJ(i, j)];
                // forest states k >= 2 (uses strictly smaller ranges only)
                for (int k = 2; k <= std::min(9, L); ++k) {
                    for (int p = 0; p <= C; ++p) {
                        long long bestw = INFLL;
                        int bestp = 0, bestm = -1, bestp1 = 0;
                        for (int mcut = i + 1; mcut <= j - k + 1; ++mcut) {
                            size_t fi = (size_t)fidx(i, mcut, 0);
                            size_t gi = (size_t)gidx(k - 1, mcut, j, 0);
                            for (int p1 = 0; p1 <= p; ++p1) {
                                long long wa = Fw[fi + p1];
                                if (wa >= INFLL) continue;
                                long long wb = Gw[gi + (p - p1)];
                                if (wb >= INFLL) continue;
                                long long w = wa + wb;
                                int pg = Fp[fi + p1] + Gp[gi + (p - p1)];
                                if (w < bestw || (w == bestw && pg < bestp)) {
                                    bestw = w; bestp = pg; bestm = mcut; bestp1 = p1;
                                }
                            }
                        }
                        if (bestm >= 0) {
                            size_t t = (size_t)gidx(k, i, j, p);
                            Gw[t] = bestw; Gp[t] = bestp;
                            Gc[t] = (bestm << 4) | bestp1;
                        }
                    }
                }
                // leaf option
                if (L <= 8) {
                    for (int md = 0; md < 3; ++md) {
                        if (!legal(i, j, md)) continue;
                        int P = node_alloc(1, md, L, 0) / 64;
                        int kc = (L + lanes[md] - 1) / lanes[md] + dec[md];
                        long long wq = (long long)kc * qq;
                        updF(i, j, 0, (long long)P * miss * tt + wq, P, 1 | (md << 1));
                        if (P <= C)
                            updF(i, j, P, (long long)P * hit * tt + wq, P,
                                 1 | (md << 1) | (1 << 3));
                    }
                }
                // internal options
                if (L >= 2) {
                    for (int b = 2; b <= std::min(9, L); ++b) {
                        for (int md = 0; md < 3; ++md) {
                            if (!legal(i, j, md)) continue;
                            int P = node_alloc(0, md, L, b) / 64;
                            int kc = ((b - 1) + lanes[md] - 1) / lanes[md] + dec[md];
                            long long wq = (long long)kc * qq;
                            for (int cch = 0; cch < 2; ++cch) {
                                int ps = cch ? P : 0;
                                if (ps > C) continue;
                                long long own = (long long)P * (cch ? hit : miss) * tt + wq;
                                size_t gi = (size_t)gidx(b, i, j, 0);
                                for (int pc = 0; pc <= C - ps; ++pc) {
                                    long long wg = Gw[gi + pc];
                                    if (wg >= INFLL) continue;
                                    updF(i, j, ps + pc, own + wg, P + Gp[gi + pc],
                                         (md << 1) | (cch << 3) | (b << 4) | (pc << 9));
                                }
                            }
                        }
                    }
                }
                // forest of one = the subtree itself
                for (int p = 0; p <= C; ++p) {
                    size_t f = (size_t)fidx(i, j, p), g = (size_t)gidx(1, i, j, p);
                    Gw[g] = Fw[f]; Gp[g] = Fp[f];
                }
            }
        }
        best.assign(C + 1, {INFLL, 0});
        for (int p = 0; p <= C; ++p) {
            size_t f = (size_t)fidx(0, R, p);
            best[p] = {Fw[f], Fp[f]};
        }
    }

    // ---- reconstruction -------------------------------------------------
    struct TNode { int kind, mode, cached, lo, span; std::vector<int> kids; };
    std::vector<TNode> arena;

    int buildF(int i, int j, int p) {
        int ch = Fc[(size_t)fidx(i, j, p)];
        if (ch < 0) throw std::runtime_error("plan reconstruction");
        int kind = ch & 1, mode = (ch >> 1) & 3, cached = (ch >> 3) & 1;
        int b = (ch >> 4) & 31, pc = (ch >> 9) & 31;
        int id = (int)arena.size();
        arena.push_back({kind, mode, cached, i, j - i, {}});
        if (kind == 0) arena[id].kids = buildG(i, j, b, pc);
        return id;
    }
    std::vector<int> buildG(int i, int j, int k, int p) {
        if (k == 1) return {buildF(i, j, p)};
        int ch = Gc[(size_t)gidx(k, i, j, p)];
        if (ch < 0) throw std::runtime_error("plan forest reconstruction");
        int mcut = (ch >> 4) & 0x3fff, p1 = ch & 15;
        std::vector<int> out;
        out.push_back(buildF(i, mcut, p1));
        std::vector<int> rest = buildG(mcut, j, k - 1, p - p1);
        out.insert(out.end(), rest.begin(), rest.end());
        return out;
    }

    // BFS-ordered flat layout for the subtree using exactly p cached pages.
    std::vector<LayoutNode> reconstruct(int p) {
        arena.clear();
        int root = buildF(0, R, p);
        std::vector<int> order{root};
        for (size_t h = 0; h < order.size(); ++h)
            for (int c : arena[order[h]].kids) order.push_back(c);
        std::vector<int> pos(arena.size(), -1);
        std::vector<LayoutNode> out;
        for (size_t t = 0; t < order.size(); ++t) pos[order[t]] = (int)t;
        for (size_t t = 0; t < order.size(); ++t) {
            const TNode& nd = arena[order[t]];
            LayoutNode ln;
            ln.kind = nd.kind; ln.mode = nd.mode; ln.cached = nd.cached;
            ln.lo = nd.lo; ln.span = nd.span;
            for (int c : nd.kids) ln.kids.push_back(pos[c]);
            out.push_back(ln);
        }
        return out;
    }

    // Exact work of a flat layout (independent of the DP values).
    long long layout_work(const std::vector<LayoutNode>& nodes) const {
        static const int lanes[3] = {4, 8, 16};
        long long work = 0;
        for (const LayoutNode& nd : nodes) {
            int b = (int)nd.kids.size();
            int K = (nd.kind == 0) ? b - 1 : nd.span;
            int P = node_alloc(nd.kind, nd.mode, nd.span, b) / 64;
            int kc = (K + lanes[nd.mode] - 1) / lanes[nd.mode] + dec[nd.mode];
            work += (long long)P * (nd.cached ? hit : miss) * T[(size_t)IJ(nd.lo, nd.lo + nd.span)]
                  + (long long)kc * Q[(size_t)IJ(nd.lo, nd.lo + nd.span)];
        }
        return work;
    }
};
