    if (total_runs > 128) { std::cout << "INVALID\n"; return 0; }

    std::cout << "OK\n";
    for (size_t ci = 0; ci < ncases; ++ci) {
        const CaseIn& cs = cases[ci];
        const CaseRuns& cr = compiled[ci];
        size_t nv = cs.versions.size();
        int C = cs.cache_pages;

        // Per-version plans (work,pages) for every exact resident-page count.
        std::vector<VersionPlan> plans(nv);
        std::vector<std::vector<OptPair>> per(nv);
        for (size_t v = 0; v < nv; ++v) {
            std::vector<U128> starts;
            std::vector<BurstData> bd;
            for (const Run& r : cr.versions[v]) starts.push_back(r.start);
            int R = (int)starts.size();
            for (const CaseIn::Burst& bu : cs.bursts) {
                if (bu.version != (int)v) continue;
                BurstData d;
                d.rep = bu.rep;
                d.cnt.assign(R, 0);
                for (int ri : cr.addr_run[&bu - &cs.bursts[0]]) d.cnt[ri]++;
                bd.push_back(std::move(d));
            }
            plans[v].run(starts, bd, C, cs.hit, cs.miss, cs.dec);
            per[v] = plans[v].best;
        }

        // Joint resident-budget combination across versions of this case.
        std::vector<OptPair> cur(C + 1, {INFLL, 0});
        std::vector<int> back(nv * (C + 1), -1);
        cur[0] = {0, 0};
        for (size_t v = 0; v < nv; ++v) {
            std::vector<OptPair> nxt(C + 1, {INFLL, 0});
            for (int q = 0; q <= C; ++q) {
                for (int p = 0; p <= q; ++p) {
                    if (cur[p].w >= INFLL || per[v][q - p].w >= INFLL) continue;
                    long long w = cur[p].w + per[v][q - p].w;
                    int pg = cur[p].p + per[v][q - p].p;
                    if (w < nxt[q].w || (w == nxt[q].w && pg < nxt[q].p)) {
                        nxt[q] = {w, pg};
                        back[v * (C + 1) + q] = p;
                    }
                }
            }
            cur = nxt;
        }
        int bestq = 0;
        for (int q = 0; q <= C; ++q)
            if (pair_less(cur[q].w, cur[q].p, cur[bestq].w, cur[bestq].p)) bestq = q;
        OptPair optimum = cur[bestq];
        std::vector<int> use(nv, 0);
        {
            int q = bestq;
            for (size_t v = nv; v-- > 0;) {
                use[v] = q - back[v * (C + 1) + q] ... ;
            }
        }
        (void)optimum; (void)use;
    }
    return 0;
}

}  // namespace

