        std::vector<std::vector<U128>> starts_of(nv);
        std::vector<std::vector<int>> hops_of(nv);
        long long image_pages = 0;
        for (size_t v = 0; v < nv; ++v) {
            const auto& runs = compiled[ci][v];
            int R = (int)runs.size();
            for (const Run& r : runs) {
                starts_of[v].push_back(r.start);
                hops_of[v].push_back(r.hop);
            }
            std::vector<BurstData> bd;
            for (const CaseIn::Burst& bu : cs.bursts) {
                if (bu.version != (int)v) continue;
                BurstData d;
                d.rep = bu.rep;
                d.cnt.assign(R, 0);
                for (int ri : bu.run_idx) d.cnt[ri]++;
                bd.push_back(std::move(d));
            }
            plans[v].run(starts_of[v], bd, C, cs.hit, cs.miss, cs.dec);
            per[v] = plans[v].best;
            image_pages += 1 + (R * 4 + 63) / 64;
        }

        // Joint resident-budget combination over the versions of this case.
        std::vector<OptPair> cur(C + 1, {INFLL, 0});
        std::vector<int> back(nv * (C + 1), -1);
        cur[0] = {0, 0};
        for (size_t v = 0; v < nv; ++v) {
            std::vector<OptPair> nxt(C + 1, {INFLL, 0});
            for (int q = 0; q <= C; ++q) {
                for (int p = 0; p <= q; ++p) {
                    if (cur[p].w >= INFLL || per[v][q - p].w >= INFLL) continue;
                    long long w = cur[p].w + per[v][q - p].w;
                    int pg = cur[p].p + per[v][q - p].p;
                    if (w < nxt[q].w || (w == nxt[q].w && pg < nxt[q].p)) {
                        nxt[q] = {w, pg};
                        back[v * (C + 1) + q] = p;
                    }
                }
            }
            cur = nxt;
        }
        int bestq = 0;
        for (int q = 0; q <= C; ++q)
            if (pair_less(cur[q].w, cur[q].p, cur[bestq].w, cur[bestq].p)) bestq = q;
        std::vector<int> use(nv, 0);
        {
            int q = bestq;
            for (size_t v = nv; v-- > 0;) {
                int p = back[v * (C + 1) + q];
                if (p < 0) throw std::runtime_error("budget backtracking");
                use[v] = q - p;
                q = p;
            }
        }

        // Rebuild every version's image from its optimal plan and answer bursts.
        std::vector<std::vector<LayoutNode>> layouts(nv);
        std::vector<std::vector<uint8_t>> images(nv);
        long long work = 0, pages = 0, resident = 0;
        for (size_t v = 0; v < nv; ++v) {
            layouts[v] = plans[v].reconstruct(use[v]);
            images[v] = build_image(starts_of[v], hops_of[v], layouts[v]);
            long long w = plans[v].layout_work(layouts[v]);
            if (w != per[v][use[v]].w) throw std::runtime_error("plan work mismatch");
            work += w;
            pages += (long long)images[v].size() / 64;
            for (const LayoutNode& nd : layouts[v])
                if (nd.cached)
                    resident += node_alloc(nd.kind, nd.mode, nd.span, (int)nd.kids.size()) / 64;
        }
        if (resident > C) throw std::runtime_error("resident budget");
        if (work != cur[bestq].w) throw std::runtime_error("objective work mismatch");

        std::cout << "OBJ " << work << ' ' << pages << '\n';
        for (size_t v = 0; v < nv; ++v) {
            std::cout << "RUNS " << starts_of[v].size() << '\n';
            for (size_t r = 0; r < starts_of[v].size(); ++r)
                std::cout << hexkey(starts_of[v][r]) << ' ' << hops_of[v][r] << '\n';
            std::cout << "IMAGE " << to_hex(images[v]) << '\n';
        }
        std::cout << "CHANGES " << (nv - 1) << '\n';
        for (size_t v = 0; v + 1 < nv; ++v) {
            std::vector<ChangeRow> rows = diff_runs(compiled[ci][v], compiled[ci][v + 1]);
