"""Cache-budgeted IPv6 packed-image compiler: JSON entry point.

Parses and validates one JSON request (protocol.py), hands the normalized
route histories to the scalar engine which compiles canonical forwarding
runs, plans the joint tree/mode/residency optimum under the shared cache
budget and builds the packed images, then emits one JSON result.
"""
import json
import sys

import native  # Build/transport helpers for the supplied scalar library.
from protocol import Invalid, MAX_INPUT, parse_request


class Engine:
    """Line-framed reader over one SOLVE stage response."""

    def __init__(self, lines):
        self.lines = lines
        self.at = 0

    def take(self):
        if self.at >= len(self.lines):
            raise RuntimeError("truncated engine output")
        line = self.lines[self.at]
        self.at += 1
        return line

    def words(self):
        return self.take().split()

    def count(self, tag):
        parts = self.words()
        if len(parts) != 2 or parts[0] != tag:
            raise RuntimeError("engine framing: " + tag)
        return int(parts[1])


def parse_hop(text):
    value = int(text)
    return None if value < 0 else value


def compile_request(cases):
    # A committed version's canonical R must be <=64 and the sum over all
    # committed versions of the whole request must be <=128; that domain is
    # checked by the forwarding compilation inside the engine (INVALID).
    lines = ["SOLVE %d" % len(cases)]
    for case in cases:
        hit, miss, dec = case["costs"]
        routes = {}
        for route, hop in case["initial"]:
            routes[route] = hop  # last initial row wins
        history = [dict(routes)]
        for tx in case["transactions"]:
            for op in tx:
                if op[0] == "set":
                    routes[op[1]] = op[2]
                else:
                    routes.pop(op[1], None)
            history.append(dict(routes))
        lines.append("%d %d %d %d %d %d %d" % (
            len(history), case["cache_pages"], hit, miss, dec[0], dec[1], dec[2]))
        for snapshot in history:
            lines.append(str(len(snapshot)))
            for (addr, length), hop in snapshot.items():
                lines.append("%032x %d %d" % (addr, length, hop))
        lines.append(str(len(case["bursts"])))
        for version, repeat, addresses in case["bursts"]:
            lines.append("%d %d %d" % (version, repeat, len(addresses)))
            for addr in addresses:
                lines.append("%032x" % addr)

    out = Engine(native.run(lines))
    if out.take() == "INVALID":
        raise Invalid()
    if out.lines[0] != "OK":
        raise RuntimeError("engine protocol")

    results = []
    for case in cases:
        work_pages = out.words()
        if len(work_pages) != 3 or work_pages[0] != "OBJ":
            raise RuntimeError("engine framing: OBJ")
        versions = []
        for _ in range(len(case["transactions"]) + 1):
            if out.count("RUNS") < 1:
                raise RuntimeError("engine framing: runs")
            out.at -= 1  # re-read with rows below
            parts = out.words()
            runs = int(parts[1])
            starts, hops = [], []
            for _ in range(runs):
                key, hop = out.words()
                starts.append(key)
                hops.append(parse_hop(hop))
            head = out.words()
            if len(head) != 2 or head[0] != "IMAGE":
                raise RuntimeError("engine framing: IMAGE")
            versions.append({"starts": starts, "hops": hops, "image": head[1]})
        if out.count("CHANGES") != len(case["transactions"]):
            raise RuntimeError("engine framing: changes")
        changes = []
        for _ in case["transactions"]:
            rows = out.count("ROWS")
            block = []
            for _ in range(rows):
                start, end, old, new = out.words()
                block.append([start, end, parse_hop(old), parse_hop(new)])
            changes.append(block)
        bursts = []
        for _ in case["bursts"]:
            answers = out.count("ANSWERS")
            block = []
            for _ in range(answers):
                words = out.words()
                hop, run, depth = int(words[0]), int(words[1]), int(words[2])
                if len(words) != 3 + depth:
                    raise RuntimeError("engine framing: path")
                block.append([parse_hop(words[0]), run, [int(x) for x in words[3:]]])
            bursts.append(block)
        results.append({
            "versions": versions,
            "changes": changes,
            "bursts": bursts,
            "objective": [int(work_pages[1]), int(work_pages[2])],
        })
    if out.at != len(out.lines):
        raise RuntimeError("engine framing: trailing output")
    return {"cases": results}


def main():
    try:
        cases = parse_request(sys.stdin.buffer.read(MAX_INPUT + 1))
        result = compile_request(cases)
    except Invalid:
        result = {"error": "invalid"}
    json.dump(result, sys.stdout, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
