U = 1 << 128

def compile_runs(routes):
    """routes: dict (addr, length) -> hop. Returns [(start, hop)] coalesced."""
    events = []
    for (s, ln), hop in routes.items():
        events.append((s, 1, ln, hop))
        end = s + (1 << (128 - ln))
        if end < U:
            events.append((end, -1, ln, hop))
    events.sort()
    active = {}
    runs = []
    prev = 0
    def top():
        best = None
        for ln in sorted(active, reverse=True):
            if active[ln]:
                return ln
        return None
    def emit(pos_from, pos_to):
        if pos_from >= pos_to:
            return
        t = top()
        hop = active[t][0] if t is not None else None  # placeholder
        hop = hops_of[t] if t is not None else None
        if not runs or runs[-1][1] != hop:
            runs.append((pos_from, hop))
    hops_of = {}
    k = 0
    while k < len(events):
        p = events[k][0]
        t = top()
        hop = hops_of.get(t) if t is not None else None
        if prev < p and (not runs or runs[-1][1] != hop):
            runs.append((prev, hop))
        while k < len(events) and events[k][0] == p:
            pos, d, ln, hop = events[k]
            if d > 0:
                active[ln] = active.get(ln, 0) + 1
                hops_of[ln] = hop
            else:
                active[ln] -= 1
            k += 1
        prev = p
    t = top()
    hop = hops_of.get(t) if t is not None else None
    if not runs or runs[-1][1] != hop:
        runs.append((prev, hop))
    return runs

def changes(runs_a, runs_b):
    out = []
    ia = ib = 0
    pos = 0
    while True:
        naU = not (ia + 1 < len(runs_a))
        nbU = not (ib + 1 < len(runs_b))
        na = runs_a[ia + 1][0] if not naU else U
        nb = runs_b[ib + 1][0] if not nbU else U
        end = min(na, nb)
        o, n = runs_a[ia][1], runs_b[ib][1]
        if o != n:
            if out and out[-1][2] == o and out[-1][3] == n and out[-1][1] == pos:
                out[-1] = (out[-1][0], end, o, n)
            else:
                out.append((pos, end, o, n))
        if end == U:
            break
        if end == na:
            ia += 1
        if end == nb:
            ib += 1
        pos = end
    return out

WIDTH = (16, 8, 4)
LANES = (4, 8, 16)

def q_t(starts, bursts):
    R = len(starts)
    Q = [[0] * (R + 1) for _ in range(R + 1)]
    T = [[0] * (R + 1) for _ in range(R + 1)]
    for rep, cnt in bursts:
        for i in range(R):
            acc = 0
            for j in range(i + 1, R + 1):
                acc += cnt[j - 1]
                Q[i][j] += rep * acc
                if acc:
                    T[i][j] += rep
    return Q, T

def brute(starts, bursts, C, hit, miss, dec):
    """All layouts for one version; returns dict resident -> (work,pages) lex-min
    plus full option list for cross-checking the combine."""
    R = len(starts)
    Q, T = q_t(starts, bursts)

    def legal(i, j, mode):
        if mode == 0:
            return True
        spread = starts[j - 1] - starts[i]
        return spread < (1 << (64 if mode == 1 else 32))

    def gen(i, j):
        L = j - i
        out = []
        if L <= 8:
            for mode in range(3):
                if not legal(i, j, mode):
                    continue
                used = 32 + L * WIDTH[mode]
                P = (used + 63) // 64
                kc = (L + LANES[mode] - 1) // LANES[mode] + dec[mode]
                for cached in (0, 1):
                    work = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                    out.append((work, P, cached * P, ('leaf', mode, cached, [])))
        if L >= 2:
            for b in range(2, min(9, L) + 1):
                # compositions of L into b positive parts
                for cuts in itertools.combinations(range(1, L), b - 1):
                    bounds = (i,) + tuple(i + c for c in cuts) + (j,)
                    subs = [gen(bounds[t], bounds[t + 1]) for t in range(b)]
                    for mode in range(3):
                        if not legal(i, j, mode):
                            continue
                        used = 32 + 4 * b + (b - 1) * WIDTH[mode]
                        P = (used + 63) // 64
                        kc = ((b - 1) + LANES[mode] - 1) // LANES[mode] + dec[mode]
                        for cached in (0, 1):
                            base = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                            for combo in itertools.product(*subs):
                                work = base + sum(c[0] for c in combo)
                                pages = P + sum(c[1] for c in combo)
                                res = cached * P + sum(c[2] for c in combo)
                                if res <= C:
                                    tree = ('int', mode, cached, [c[3] for c in combo])
                                    out.append((work, pages, res, tree))
        return out

    options = gen(0, R)
    return options

def brute_case(versions, bursts, C, costs, max_options=400000):
    """versions: list of route dicts; bursts: list of (version, rep, [run-count dicts...])
    Actually bursts: list of (version, rep, addresses as run-index lists computed by caller)."""
    hit, miss, dec = costs
    per = []
    for v, routes in enumerate(versions):
        runs = compile_runs(routes)
        starts = [s for s, _ in runs]
        bl = []
        for (bv, rep, run_ids) in bursts:
            if bv != v:
                continue
            cnt = [0] * len(starts)
            for r in run_ids:
                cnt[r] += 1
            bl.append((rep, cnt))
        opts = brute(starts, bl, C, hit, miss, dec)
        if len(opts) > max_options:
            return None  # skip: too large for brute force
        byres = {}
        for w, p, r, _ in opts:
            if r not in byres or (w, p) < byres[r]:
                byres[r] = (w, p)
        per.append((opts, byres, runs))
    # full-product combine if feasible, else grouped combine (both valid)
    best = None
    lists = [o for (o, _, _) in per]
    total = 1
    for l in lists:
        total *= max(1, len([x for x in l if x[2] <= C]))
    if total <= 3000000 and len(lists) <= 3:
        for combo in itertools.product(*lists):
            res = sum(c[2] for c in combo)
            if res > C:
                continue
            w = sum(c[0] for c in combo)
            p = sum(c[1] for c in combo)
            if best is None or (w, p) < best:
                best = (w, p)
    else:
        keys = [sorted(byres) for (_, byres, _) in per]
        for combo in itertools.product(*keys):
            if sum(combo) > C:
                continue
            w = sum(per[t][1][combo[t]][0] for t in range(len(per)))
            p = sum(per[t][1][combo[t]][1] for t in range(len(per)))
            if best is None or (w, p) < best:
                best = (w, p)
    pages_const = sum(1 + (len(runs) * 4 + 63) // 64 for (_, _, runs) in per)
    return (best[0], best[1] + pages_const), [runs for (_, _, runs) in per]
