import sys

sys.path.insert(0, '/workspace/tmp/tests')
sys.path.insert(0, '/workspace')
import brutelib
from audit import audit

U = 1 << 128

def rand_key(rng, kind):
    if kind == 0:
        return rng.randrange(U)
    if kind == 1:
        return rng.choice([0, 1, 2, U - 1, U - 2, (1 << 64), (1 << 127)])
    return rng.randrange(1 << 16)

def fmt_addr(a):
    h = format(a, '032x')
    return ':'.join(h[i:i+4] for i in range(0, 32, 4))

def fmt_prefix(r):
    s, ln = r
    h = format(s, '032x')
    return ':'.join(h[i:i+4] for i in range(0, 32, 4)) + '/' + str(ln)

def gen_case(rng, max_routes=5, max_ver=4, max_bursts=4):
    nv = rng.randint(1, max_ver)
    def rand_route():
        length = rng.choice([0, 1, 32, 64, 96, 127, 128, rng.randint(0, 128)])
        size = 1 << (128 - length)
        start = (rand_key(rng, rng.randint(0, 2)) // size) * size
        return (start, length)
    initial = []
    routes = {}
    for _ in range(rng.randint(0, max_routes)):
        r = rand_route()
        hop = rng.choice([0, 1, 2, 7, 2147483647, rng.randint(0, 10)])
        initial.append((r, hop))
        routes[r] = hop
    history = [dict(routes)]
    transactions = []
    for _ in range(nv - 1):
        txrow = []
        for _ in range(rng.randint(0, 3)):
            if rng.random() < 0.6:
                r = rand_route()
                hop = rng.randint(0, 5)
                txrow.append(('set', r, hop))
                routes[r] = hop
            else:
                r = rand_route()
                txrow.append(('erase', r, None))
                routes.pop(r, None)
        transactions.append(txrow)
        history.append(dict(routes))
    pool = [0, 1, U - 1, rand_key(rng, 0)]
    for r in list(routes) + [rr for (rr, _) in initial]:
        pool.append(r[0])
        pool.append(r[0] + (1 << (128 - r[1])) - 1 if r[1] > 0 else U - 1)
        pool.append(min(U - 1, r[0] + (1 << max(0, 127 - r[1]))))
    pool = [min(x, U - 1) for x in pool]
    bursts = []
    for _ in range(rng.randint(0, max_bursts)):
        v = rng.randrange(nv)
        rep = rng.choice([1, 2, 5, 1000000, rng.randint(1, 50)])
        addrs = [rng.choice(pool) for _ in range(rng.randint(0, 5))]
        bursts.append((v, rep, addrs))
    cache_pages = rng.randint(0, 3)
    hit = rng.randint(1, 16)
    miss = rng.randint(hit, 32)
    dec = [rng.randint(0, 16) for _ in range(3)]
    return {
        'history': history, 'transactions': transactions, 'bursts': bursts,
        'cache_pages': cache_pages, 'costs': (hit, miss, dec),
    }, initial

def build_request(rng, ncases=1, R_cap=5):
    cases, raw_cases = [], []
    for _ in range(ncases * 6):
        if len(cases) >= ncases:
