            gv.append({'starts': [format(s, '032x') if s < U else '1' + '0' * 32
                                  for s, _ in runs],
                       'hops': [hop for _, hop in runs]})
        ch = []
        for t in range(len(case['transactions'])):
            rows = brutelib.changes(brutelib.compile_runs(case['history'][t]),
                                    brutelib.compile_runs(case['history'][t + 1]))
            ch.append([[format(a, '032x') if a < U else '1' + '0' * 32,
                        format(b, '032x') if b < U else '1' + '0' * 32, o, n]
                       for (a, b, o, n) in rows])
        # per-version brute + combined optimum
        per = []
        for v, h in enumerate(case['history']):
            runs = brutelib.compile_runs(h)
