            json.dumps({'request': request, 'actual': actual, 'gold': gold},
                       default=str))
        return False
    if verbose:
        print('seed', seed, 'ok', [c['objective'] for c in gold_cases])
    return True

if __name__ == '__main__':
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    ncases = int(sys.argv[3]) if len(sys.argv) > 3 else 1
    R_cap = int(sys.argv[4]) if len(sys.argv) > 4 else 5
